/**
 * Contract between the agent and its clients (the Perch overlay, mirrored in
 * Sources/PerchCore/Protocol.swift, and claude-panel's Pi panel), over a WebSocket at
 * ws://127.0.0.1:PANEL_PORT/ws?token=<pairing token>, or the Mac's LAN address with `--lan`.
 * The agent sends a hello and a snapshot on connect, then one message per change. The Pi panel shows sessions
 * that are `live || pinned`; Perch shows pinned ones and those working or waiting on the user.
 */

export const PANEL_PORT = 7778;

/** Pairing file the panel loads from ./config.json; generated by the agent. */
export interface PanelConfig {
  /** Ways to reach the agent, tried in order until one connects: ws://<address>:PANEL_PORT/ws */
  agentUrls: string[];
  token: string;
}

export const SESSION_STATES = [
  "idle", // started, no prompt yet
  "working",
  "needs_permission",
  "needs_input", // a question, a plan to review, or otherwise waiting on the user
  "compacting",
  "done", // finished its turn: the user's move
  "error",
  "ended", // process gone
] as const;

export type SessionState = (typeof SESSION_STATES)[number];

export interface SessionIcon {
  /** Sprite sheet id. */
  character: string;
  /** "#rrggbb" */
  color: string;
}

export const DEFAULT_ICON: SessionIcon = { character: "default", color: "#d97757" };

export interface PanelSession {
  id: string;
  name: string;
  cwd: string;
  state: SessionState;
  /** Short detail for the tile, e.g. "Bash: npm test". */
  activity: string | null;
  /** The Claude process is running. */
  live: boolean;
  /** Epoch ms of the last state change. */
  stateSince: number;
  pinned: boolean;
  /** Order among pinned sessions; null when not pinned. */
  position: number | null;
  icon: SessionIcon;
}

/** A desktop-app session the panel can pin, running or not. */
export interface LibraryEntry {
  id: string;
  name: string;
  cwd: string;
  /** Epoch ms of its last activity. */
  lastActivityAt: number;
  pinned: boolean;
}

/** Goes up when a message changes in a way an older client would misread. New message types don't count: clients ignore the ones they don't know. */
export const PROTOCOL_VERSION = 1;

export type ServerMessage =
  | { type: "hello"; protocol: number; agent: string } // first on every connection; `agent` is the agent's version
  | { type: "snapshot"; sessions: PanelSession[]; focusedId: string | null }
  | { type: "session"; session: PanelSession }
  | { type: "removed"; id: string }
  | { type: "focus"; id: string | null } // the session in front in the desktop app; null when none
  | { type: "library"; sessions: LibraryEntry[] } // reply to a library request, most recent first
  | { type: "error"; message: string };

/** `pin` and `icon` also accept a desktop session that isn't running: the agent starts tracking it. */
export type ClientMessage =
  | { type: "open"; id: string }
  | { type: "pin"; id: string; pinned: boolean }
  | { type: "icon"; id: string; icon: SessionIcon } // pins the session if it isn't yet
  | { type: "library" };
